package vn.smarttravel.catalog.taxonomy.repository;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.http.HttpStatus;
import org.springframework.web.server.ResponseStatusException;
import vn.smarttravel.catalog.places.repository.CatalogRepository;

@Repository
public class TaxonomyRepository {
    private final JdbcTemplate db;private final CatalogRepository events;
    public TaxonomyRepository(JdbcTemplate db,CatalogRepository events){this.db=db;this.events=events;}
    private String table(String kind){if(!Set.of("categories","tags","amenities","destinations","geographic-units").contains(kind))throw new ResponseStatusException(HttpStatus.NOT_FOUND);return kind.replace('-','_');}
    private String key(String kind){return switch(kind){case "categories"->"category_id";case "tags"->"tag_id";case "amenities"->"amenity_id";case "destinations"->"destination_id";default->"geographic_unit_id";};}
    public List<Map<String,Object>> list(String kind){return db.queryForList("SELECT "+key(kind)+" FROM catalog."+table(kind)+" ORDER BY "+key(kind)).stream().map(row->get(kind,(UUID)row.get(key(kind)))).toList();}
    public Map<String,Object> get(String kind,UUID id){var rows=db.queryForList("SELECT * FROM catalog."+table(kind)+" WHERE "+key(kind)+"=?",id);if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND);var row=rows.getFirst();if(kind.equals("destinations"))row.put("geographic_unit_ids",db.queryForList("SELECT geographic_unit_id FROM catalog.destination_geo WHERE destination_id=? ORDER BY geographic_unit_id",UUID.class,id));if(kind.equals("geographic-units"))row.put("aliases",db.queryForList("SELECT alias FROM catalog.geographic_aliases WHERE geographic_unit_id=? ORDER BY normalized_alias",String.class,id));return row;}
    private UUID optionalId(Object value){return value==null?null:UUID.fromString(value.toString());}
    private void parent(String kind,UUID id,UUID parent){
        if(parent==null)return;if(id.equals(parent))throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"Hierarchy cycle");String table=table(kind),key=key(kind);get(kind,parent);
        Boolean cycle=db.queryForObject("WITH RECURSIVE ancestors AS (SELECT "+key+",parent_id FROM catalog."+table+" WHERE "+key+"=? UNION SELECT u."+key+",u.parent_id FROM catalog."+table+" u JOIN ancestors a ON a.parent_id=u."+key+") SELECT EXISTS(SELECT 1 FROM ancestors WHERE "+key+"=?)",Boolean.class,parent,id);if(Boolean.TRUE.equals(cycle))throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"Hierarchy cycle");
    }
    private void lockHierarchy(String kind){db.execute("SELECT pg_advisory_xact_lock("+(kind.equals("categories")?8240101:8240102)+")");}
    @Transactional public Map<String,Object> create(String kind,Map<String,Object> body,UUID actor){vn.smarttravel.catalog.infrastructure.persistence.repository.UserMutationFence.acquire(db,actor);
        body=new LinkedHashMap<>(body);body.putIfAbsent("code",UUID.randomUUID().toString());if(kind.equals("geographic-units")){body.putIfAbsent("unit_type",body.get("level"));body.putIfAbsent("valid_from",java.time.LocalDate.now().toString());}table(kind);UUID id=body.containsKey("id")?UUID.fromString(body.get("id").toString()):UUID.randomUUID();String name=Objects.toString(body.getOrDefault("name_vi",body.get("name")),"").trim();if(name.isBlank()||name.length()>1024)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid name");UUID parent=optionalId(body.get("parent_id"));
        switch(kind){
            case "categories"->{lockHierarchy(kind);parent(kind,id,parent);db.update("INSERT INTO catalog.categories(category_id,parent_id,code,name_vi,name_en,active) VALUES(?,?,?,?,?,?)",id,parent,body.get("code"),name,body.get("name_en"),body.getOrDefault("active",true));events.emit("catalog.category.changed.v1",id,1,Map.of("category_id",id,"active",body.getOrDefault("active",true),"name",name));}
            case "tags","amenities"->db.update("INSERT INTO catalog."+table(kind)+"("+key(kind)+",code,name_vi,name_en,active) VALUES(?,?,?,?,?)",id,body.get("code"),name,body.get("name_en"),body.getOrDefault("active",true));
            case "destinations"->{db.update("INSERT INTO catalog.destinations(destination_id,name_vi,name_en,destination_type,summary,status) VALUES(?,?,?,?,?,?)",id,name,body.get("name_en"),body.getOrDefault("destination_type","REGION"),body.get("summary"),body.getOrDefault("status","PUBLISHED"));memberships(id,body);events.emit("catalog.destination.changed.v1",id,1,get(kind,id));}
            default->{lockHierarchy(kind);parent(kind,id,parent);Object from=body.get("valid_from"),to=body.get("valid_to");if(from==null)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"valid_from required");
                Integer overlaps=db.queryForObject("SELECT count(*) FROM catalog.geographic_units WHERE unit_type=? AND code=? AND daterange(valid_from,valid_to,'[]') && daterange(?::date,?::date,'[]')",Integer.class,body.get("unit_type"),body.get("code"),from,to);if(overlaps>0)throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"Effective date overlap");
                if(parent!=null){Integer valid=db.queryForObject("SELECT count(*) FROM catalog.geographic_units WHERE geographic_unit_id=? AND valid_from<=?::date AND (valid_to IS NULL OR (?::date IS NOT NULL AND valid_to>=?::date))",Integer.class,parent,from,to,to);if(valid==0)throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"Parent effective dates mismatch");}
                db.update("INSERT INTO catalog.geographic_units(geographic_unit_id,parent_id,unit_type,code,name_vi,name_en,version,valid_from,valid_to,status) VALUES(?,?,?,?,?,?,?,?::date,?::date,?)",id,parent,body.get("unit_type"),body.get("code"),name,body.get("name_en"),body.getOrDefault("version",1),from,to,body.getOrDefault("status","ACTIVE"));
            }
        }
        if(kind.equals("geographic-units")&&body.containsKey("aliases"))for(Object alias:(List<?>)body.get("aliases"))db.update("INSERT INTO catalog.geographic_aliases(alias_id,geographic_unit_id,alias,normalized_alias,valid_from) VALUES(?,?,?,?,current_date)",UUID.randomUUID(),id,alias,CatalogRepository.normalize(alias.toString()));return get(kind,id);
    }
    private void memberships(UUID destination,Map<String,Object> body){if(body.containsKey("geographic_unit_ids")){db.update("DELETE FROM catalog.destination_geo WHERE destination_id=?",destination);for(Object id:(List<?>)body.get("geographic_unit_ids"))db.update("INSERT INTO catalog.destination_geo(destination_id,geographic_unit_id) VALUES(?,?)",destination,UUID.fromString(id.toString()));}}
    @Transactional public Map<String,Object> update(String kind,UUID id,Long expected,Map<String,Object> body,UUID actor){vn.smarttravel.catalog.infrastructure.persistence.repository.UserMutationFence.acquire(db,actor);
        if(kind.equals("categories")||kind.equals("geographic-units"))lockHierarchy(kind);var current=get(kind,id);
        if(kind.equals("geographic-units")){if(expected==null)throw new ResponseStatusException(HttpStatus.valueOf(428));if(((Number)current.get("version")).longValue()!=expected)throw new ResponseStatusException(HttpStatus.CONFLICT);UUID parent=body.containsKey("parent_id")?optionalId(body.get("parent_id")):(UUID)current.get("parent_id");parent(kind,id,parent);db.update("INSERT INTO catalog.geographic_aliases(alias_id,geographic_unit_id,alias,normalized_alias,valid_from) VALUES(?,?,?,?,current_date) ON CONFLICT DO NOTHING",UUID.randomUUID(),id,current.get("name_vi"),CatalogRepository.normalize(current.get("name_vi").toString()));db.update("UPDATE catalog.geographic_units SET name_vi=coalesce(?,name_vi),parent_id=?,unit_type=coalesce(?,unit_type),version=version+1 WHERE geographic_unit_id=?",body.get("name"),parent,body.getOrDefault("unit_type",body.get("level")),id);if(body.containsKey("aliases"))for(Object alias:(List<?>)body.get("aliases"))db.update("INSERT INTO catalog.geographic_aliases(alias_id,geographic_unit_id,alias,normalized_alias,valid_from) VALUES(?,?,?,?,current_date) ON CONFLICT DO NOTHING",UUID.randomUUID(),id,alias,CatalogRepository.normalize(alias.toString()));return get(kind,id);}
        if(kind.equals("destinations")){if(expected==null)throw new ResponseStatusException(HttpStatus.valueOf(428));if(db.update("UPDATE catalog.destinations SET name_vi=coalesce(?,name_vi),summary=coalesce(?,summary),status=coalesce(?,status),version=version+1,updated_at=now() WHERE destination_id=? AND version=?",body.getOrDefault("name_vi",body.get("name")),body.get("summary"),body.get("status"),id,expected)==0)throw new ResponseStatusException(HttpStatus.CONFLICT);memberships(id,body);events.emit("catalog.destination.changed.v1",id,expected+1,get(kind,id));}
        else{if(expected!=null&&db.update("UPDATE catalog."+table(kind)+" SET version=version+1 WHERE "+key(kind)+"=? AND version=?",id,expected)!=1)throw new ResponseStatusException(HttpStatus.CONFLICT);if(expected==null)db.update("UPDATE catalog."+table(kind)+" SET version=version+1 WHERE "+key(kind)+"=?",id);if(kind.equals("categories")&&body.containsKey("parent_id")){UUID parent=optionalId(body.get("parent_id"));parent(kind,id,parent);db.update("UPDATE catalog.categories SET parent_id=? WHERE category_id=?",parent,id);}if(body.containsKey("name")||body.containsKey("name_vi"))db.update("UPDATE catalog."+table(kind)+" SET name_vi=? WHERE "+key(kind)+"=?",body.getOrDefault("name_vi",body.get("name")),id);if(body.containsKey("active"))db.update("UPDATE catalog."+table(kind)+" SET active=? WHERE "+key(kind)+"=?",body.get("active"),id);if(kind.equals("categories")){if(body.containsKey("active"))db.update("UPDATE catalog.categories SET active=? WHERE category_id=?",body.get("active"),id);events.emit("catalog.category.changed.v1",id,((Number)get(kind,id).get("version")).longValue(),get(kind,id));}}
        return get(kind,id);
    }
    @Transactional public void delete(String kind,UUID id,Long expected,UUID actor){vn.smarttravel.catalog.infrastructure.persistence.repository.UserMutationFence.acquire(db,actor);if(kind.equals("categories"))update(kind,id,expected,Map.of("active",false),actor);else if(kind.equals("destinations"))update(kind,id,expected,Map.of("status","ARCHIVED"),actor);else if(kind.equals("geographic-units")){get(kind,id);if(expected==null)throw new ResponseStatusException(HttpStatus.valueOf(428));if(db.update("UPDATE catalog.geographic_units SET status='RETIRED',version=version+1 WHERE geographic_unit_id=? AND version=?",id,expected)!=1)throw new ResponseStatusException(HttpStatus.CONFLICT);}else update(kind,id,expected,Map.of("active",false),actor);}
}
